      "parameters": {
        "jsCode": "return items.map((item) => {\n  const j = item.json || {};\n\n  const text = String(j.complaintText || '').toLowerCase();\n  const subj = String(j.subject || '').toLowerCase();\n\n  // Deterministic \"repeat\" rule for demo/testing:\n  // - repeat if subject/text contains \"wieder\" or \"erneut\" or a marker \"#repeat\"\n  const repeat = /\\bwieder\\b|\\berneut\\b|#repeat/.test(text) || /\\bwieder\\b|\\berneut\\b|#repeat/.test(subj);\n\n  // Deterministic previous cases\n  const previousCases = repeat\n    ? [\n        {\n          complaintId: 'RKL-20250110-101500',\n          date: '2025-01-10',\n          summary: 'Lieferverzögerung Einsatzmittel, Rückmeldung Lieferant verspätet',\n          outcome: 'Gutschrift + Prozessanpassung'\n        }\n      ]\n    : [];\n\n  // Deterministic known facts based on keywords\n  const knownFacts = {\n    keywords: {\n      delayMentioned: /versp(ä|ae)tet|verz(ö|oe)ger/.test(text),\n      communicationMentioned: /kommunikation|r(ü|ue)ckmeldung|antwort/.test(text)\n    },\n    assumptions: {\n      likelyRootCause: /versp(ä|ae)tet|verz(ö|oe)ger/.test(text)\n        ? 'Delay in inbound logistics or supplier dispatch'\n        : 'Unclear',\n      needsSupplierStatement: Boolean(j.supplierInvolved)\n    },\n    internalChecksSuggested: [\n      'Check PO/order timeline',\n      'Check shipment tracking (carrier)',\n      'Check supplier confirmation timestamps',\n      'Check internal comms (ticket/email thread)'\n    ]\n  };\n\n  // Normalize departmentsAffected to array\n  const departmentsAffected = Array.isArray(j.departmentsAffected)\n    ? j.departmentsAffected\n    : (typeof j.departmentsAffected === 'string' && j.departmentsAffected.trim())\n      ? [j.departmentsAffected]\n      : [];\n\n  // Kick-off decision (deterministic rules)\n  const severity = Number(j.severity || 0);\n  const kickoffRequired = repeat === true || severity >= 4 || departmentsAffected.length >= 2;\n  const kickoffReason = repeat\n    ? 'Wiederholreklamation'\n    : (severity >= 4)\n      ? 'Hohe Schwere'\n      : (departmentsAffected.length >= 2)\n        ? 'Mehrere Abteilungen betroffen'\n        : 'Kein Kick-off nötig';\n\n  // Draft: customer email\n  const complaintId = String(j.complaintId || 'RKL-UNKNOWN');\n  const customerName = String(j.customerName || '');\n\n  const customerEmailDraftSubject = `Ihre Reklamation ${complaintId} – Eingangsbestätigung & nächste Schritte`;\n  const customerEmailDraftBody =\n`Hallo ${customerName || 'und Guten Tag'},\n\nvielen Dank für Ihre Nachricht. Wir bestätigen den Eingang Ihrer Reklamation (Referenz: ${complaintId}).\n\nZusammenfassung Ihres Anliegens (aus Ihrer Nachricht):\n\"${String(j.complaintText || '')}\"\n\nAktueller Status / nächste Schritte:\n- Interne Prüfung und Datensichtung (${departmentsAffected.join('/') || 'zuständige Stellen'})\n- Abgleich mit bisherigen Fällen (Wiederholreklamation: ${repeat ? 'Ja' : 'Nein'})\n- ${kickoffRequired ? `Kick-off-Meeting intern geplant (Grund: ${kickoffReason})` : 'Kein internes Kick-off erforderlich laut aktueller Einschätzung'}\n\nHinweis: Dies ist ein Entwurf und wird vor dem Versand fachlich geprüft.\n\nMit freundlichen Grüßen\nIhre Organisation\n`;\n\n  // Draft: supplier email (optional)\n  const forwardToSupplier = Boolean(j.forwardToSupplier);\n  const supplierEmailDraftTo = 'supplier@example.com';\n  const supplierEmailDraftSubject = `Anfrage zur Reklamation ${complaintId} – Bitte um Stellungnahme`;\n  const supplierEmailDraftBody =\n`Guten Tag,\n\nwir bitten um Unterstützung zur Reklamation (Referenz: ${complaintId}).\n\nBekannte Fakten (intern recherchiert):\n${JSON.stringify(knownFacts, null, 2)}\n\nKundenschilderung (Auszug):\n\"${String(j.complaintText || '')}\"\n\nBitte um Rückmeldung zu:\n1) Ursachenanalyse\n2) Betroffene Chargen/Sendungen\n3) Korrektur- und Präventionsmaßnahmen\n4) Erwartete Zeitleiste\n\nHinweis: Dies ist ein Entwurf und wird vor dem Versand fachlich geprüft.\n\nMit freundlichen Grüßen\nIhre Organisation\n`;\n\n  item.json = {\n    ...j,\n    repeat,\n    previousCases,\n    knownFacts,\n    departmentsAffected,\n    kickoffRequired,\n    kickoffReason,\n    customerEmailDraftSubject,\n    customerEmailDraftBody,\n    forwardToSupplier,\n    supplierEmailDraftTo: forwardToSupplier ? supplierEmailDraftTo : undefined,\n    supplierEmailDraftSubject: forwardToSupplier ? supplierEmailDraftSubject : undefined,\n    supplierEmailDraftBody: forwardToSupplier ? supplierEmailDraftBody : undefined\n  };\n\n  return item;\n});"
      },
      "id": "5f77b6a4-3f1a-4e34-9caa-8f90b56b9c42",
      "name": "Repeat Check + Research + Drafts (Code)",
      "type": "n8n-nodes-base.code",
      "typeVersion": 2,
      "position": [
        860,
        220
      ]
    },
    {
      "parameters": {
        "jsCode": "return items.map((item) => {\n  const j = item.json || {};\n\n  const result = {\n    complaintId: j.complaintId,\n    channel: j.channel,\n    customer: {\n      name: j.customerName,\n      email: j.customerEmail\n    },\n    subject: j.subject,\n    severity: j.severity,\n    repeat: j.repeat,\n    kickoff: {\n      required: j.kickoffRequired,\n      reason: j.kickoffReason\n    },\n    departmentsAffected: j.departmentsAffected,\n    research: {\n      knownFacts: j.knownFacts,\n      previousCases: j.previousCases\n    },\n    drafts: {\n      customerEmail: {\n        subject: j.customerEmailDraftSubject,\n        body: j.customerEmailDraftBody\n      },\n      supplierEmail: j.forwardToSupplier\n        ? {\n            to: j.supplierEmailDraftTo,\n            subject: j.supplierEmailDraftSubject,\n            body: j.supplierEmailDraftBody\n          }\n        : null\n    }\n  };\n\n  return { json: { result } };\n});"
